* {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  font-family: var(--font);
  background: var(--bg);
  color: var(--text);
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

/* Skip link */
.skip-link {
  position: absolute;
  left: 12px;
  top: -100px;
  background: var(--text);
  color: #fff;
  padding: 10px 14px;
  border-radius: 8px;
  text-decoration: none;
  z-index: 100;
}
.skip-link:focus {
  top: 12px;
}

/* Header */
.site-header {
  background: var(--surface);
  border-bottom: 1px solid var(--border);
}
.site-header__inner {
  max-width: 760px;
  margin: 0 auto;
  padding: 18px 24px;
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  color: var(--text);
  font-weight: 600;
  letter-spacing: -0.01em;
}
.brand__mark {
  font-size: 1.4rem;
}
.brand:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 4px;
  border-radius: 4px;
}

/* Page */
.page {
  max-width: 760px;
  margin: 0 auto;
  padding: 56px 24px 72px;
}

/* Hero */
.hero {
  text-align: left;
  margin-bottom: 40px;
}
.eyebrow {
  display: inline-block;
  margin: 0 0 14px;
  padding: 4px 10px;
  background: var(--accent-soft);
  color: var(--accent);
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  border-radius: 999px;
}
.hero h1 {
  font-size: clamp(1.9rem, 4vw + 1rem, 2.75rem);
  line-height: 1.15;
  letter-spacing: -0.02em;
  margin: 0 0 14px;
}
.lede {
  font-size: 1.075rem;
  color: var(--text-muted);
  margin: 0;
  max-width: 60ch;
}

/* FAQ list */
.faq {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.example {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow-sm);
  overflow: hidden;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}
.example:hover {
  border-color: var(--border-strong);
}
.example:has(.faq__trigger[aria-expanded="true"]) {
  border-color: var(--accent);
  box-shadow: var(--shadow-md);
}

.faq__q {
  margin: 0;
  font-size: 1rem;
  font-weight: 500;
}

.faq__trigger {
  /* reset */
  appearance: none;
  background: transparent;
  border: 0;
  font: inherit;
  color: inherit;
  text-align: left;
  cursor: pointer;
  /* layout */
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 20px 22px;
  border-radius: var(--radius);
}
.faq__trigger:focus {
  outline: none;
}
.faq__trigger:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: -2px;
}

.faq__label {
  font-size: 1.05rem;
  font-weight: 600;
  letter-spacing: -0.005em;
  color: var(--text);
}

.faq__icon {
  flex-shrink: 0;
  position: relative;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--accent-soft);
  transition: background-color 0.15s ease, transform 0.2s ease;
}
.faq__icon::before,
.faq__icon::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: 12px;
  height: 2px;
  background: var(--accent);
  border-radius: 2px;
  transform: translate(-50%, -50%);
  transition: transform 0.2s ease;
}
.faq__icon::after {
  transform: translate(-50%, -50%) rotate(90deg);
}
.faq__trigger[aria-expanded="true"] .faq__icon {
  background: var(--accent);
}
.faq__trigger[aria-expanded="true"] .faq__icon::before,
.faq__trigger[aria-expanded="true"] .faq__icon::after {
  background: #fff;
}
.faq__trigger[aria-expanded="true"] .faq__icon::after {
  transform: translate(-50%, -50%) rotate(0deg);
}

/* Panel */
.details {
  padding: 0 22px 22px;
  color: var(--text-muted);
  font-size: 1rem;
  border-top: 1px solid var(--border);
  margin-top: 0;
}
.details p {
  margin: 18px 0 0;
  max-width: 62ch;
}
.details[hidden] {
  display: none;
}

/* Callout */
.callout {
  margin-top: 48px;
  padding: 28px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow-sm);
}
.callout h2 {
  margin: 0 0 8px;
  font-size: 1.25rem;
  letter-spacing: -0.01em;
}
.callout p {
  margin: 0;
  color: var(--text-muted);
}

/* Footer */
.site-footer {
  border-top: 1px solid var(--border);
  background: var(--surface);
}
.site-footer p {
  max-width: 760px;
  margin: 0 auto;
  padding: 20px 24px;
  color: var(--text-muted);
  font-size: 0.9rem;
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition: none !important;
    animation: none !important;
  }
}

/* Forced colors / high contrast */
@media (forced-colors: active) {
  .example {
    border: 1px solid CanvasText;
  }
  .faq__trigger:focus-visible {
    outline: 2px solid Highlight;
  }
  .faq__icon {
    background: ButtonFace;
    border: 1px solid ButtonText;
    forced-color-adjust: none;
  }
  .faq__icon::before,
  .faq__icon::after {
    background: ButtonText;
  }
}
