* {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  font-family: var(--font);
  background: var(--bg);
  color: var(--text);
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

/* Skip link */
.skip-link {
  position: absolute;
  left: 12px;
  top: -100px;
  background: var(--text);
  color: #fff;
  padding: 10px 14px;
  border-radius: 8px;
  text-decoration: none;
  z-index: 100;
}
