const { AxePuppeteer } = require('@axe-core/puppeteer');
const puppeteer = require('puppeteer');
const path = require('path');

(async () => {
  const browser = await puppeteer.launch({ args: ['--no-sandbox'] });
  const page = await browser.newPage();
  const url = 'file://' + path.resolve(__dirname, 'index.html');
  await page.goto(url, { waitUntil: 'networkidle0' });

  // Test collapsed state
  let results = await new AxePuppeteer(page).analyze();
  console.log('=== COLLAPSED STATE ===');
  console.log('Violations:', results.violations.length);
  for (const v of results.violations) {
    console.log(`- [${v.impact}] ${v.id}: ${v.help}`);
    for (const n of v.nodes) console.log('   target:', n.target, '\n   ', n.failureSummary);
  }

  // Expand all and re-test
  await page.evaluate(() => {
    document.querySelectorAll('.faq__trigger').forEach(b => b.click());
  });
  results = await new AxePuppeteer(page).analyze();
  console.log('=== EXPANDED STATE ===');
  console.log('Violations:', results.violations.length);
  for (const v of results.violations) {
    console.log(`- [${v.impact}] ${v.id}: ${v.help}`);
    for (const n of v.nodes) console.log('   target:', n.target, '\n   ', n.failureSummary);
  }

  await browser.close();
})();

